def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    qualifying_years = []
    if v1 < 150000:
        qualifying_years.append(2019)
    if v2 < 150000:
        qualifying_years.append(2018)

    result = qualifying_years[0] if len(qualifying_years) == 1 else qualifying_years

    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "threshold": 150000,
            "qualifying_years": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
